public static int indexOfExtension(String filename) {
  if (filename == null) {
    return -1;
  }

  int lastSeparatorIndex = indexOfLastSeparator(filename);
  if (lastSeparatorIndex == -1) {
    return -1;
  }

  int lastDotIndex = filename.indexOf('.');
  if (lastDotIndex == -1) {
    return -1;
  }

  // Check that there is no directory separator after the last dot
  int lastSeparatorAfterDotIndex = indexOfLastSeparator(filename, lastDotIndex + 1);
  if (lastSeparatorAfterDotIndex != -1) {
    return -1;
  }

  return lastDotIndex;
}

