public static String findAndSubst(String key, Properties props) {
boolean invalidKey = key == null || key.isEmpty();
boolean invalidProps = props == null || props.isEmpty();

// If the key or properties are invalid, return an empty string
if (invalidKey || invalidProps) {
return "";
}

// Get the value for the key from the properties
String value = props.getProperty(key);

// If the value is null or empty, return an empty string
if (value == null || value.isEmpty()) {
return "";
}

// Perform variable substitution on the value
Map<String, String> variables = new HashMap<>();
for (Object propKey : props.keySet()) {
variables.put((String) propKey, props.getProperty((String) propKey));
}

StringEvaluator evaluator = new StringEvaluator();
evaluator.setDefaultVariables(variables);
String substitutedValue = evaluator.evaluate(value);

return substitutedValue;
}

