protected int removeUnusedNodes(Directory directory, Map<String, Integer> referenceCounts) throws IOException {
        Validate.notNull(directory, "directory must not be null");
        Validate.notNull(referenceCounts, "referenceCounts must not be null");

        int removedNodes = 0;
        Set<String> inactiveNodes = new HashSet<>();

        // Iterate over all nodes in the category tree
        for (Map.Entry<String, Integer> entry : referenceCounts.entrySet()) {
            String nodePath = entry.getKey();
            int referenceCount = entry.getValue();

            // If the node is inactive, add it to the set of inactive nodes
            if (referenceCount == 0) {
                inactiveNodes.add(nodePath);
            }
        }

        // Iterate over all inactive nodes and delete them
        for (String inactiveNode : inactiveNodes) {
            // Delete the node from the category tree
            try {
                directory.deleteFile(inactiveNode);
                removedNodes++;
            } catch (IOException e) {
                LOGGER.error("Error deleting node " + inactiveNode, e);
            }
        }

        return removedNodes;
    }

