    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    int numberOfRanges = Math.abs(duration / FETCH_DATA_DURATION);
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long timeRangeStart = start;
        long timeRangeEnd = start + FETCH_DATA_DURATION;
        for (int i = 0; i < numberOfRanges; i++) {
            timeRanges.add(new TimeRange(timeRangeStart, timeRangeEnd));
            timeRangeStart = timeRangeEnd;
            timeRangeEnd = timeRangeEnd + FETCH_DATA_DURATION;
        }
        if (timeRangeEnd < end) {
            timeRanges.add(new TimeRange(timeRangeStart, end));
        }
    }
    return timeRanges;
}

