public static long compressTimeBucket(long timeBucket, int dayStep){
	int numDays = dayStep; // The number of days to subtract from the time bucket to get the new time bucket
	int daysToSubtract = numDays; // The number of days already subtracted from the time bucket to prevent negative time buckets
	while (daysToSubtract > 0)
	{
		// Subtract the number of days from the time bucket
		timeBucket -= daysToSubtract;
		// Add the number of days to the number of days already subtracted
		daysToSubtract += numDays;
	}
	return timeBucket; // Return the new time bucket
}

