public final byte[] toByteArray() {
    if (getBufferList() == null || getBufferList().isEmpty()) {
        return new byte[0];
    }
    int totalLength = 0;
    for (ByteBuffer buffer : getBufferList()) {
        totalLength += buffer.limit();
    }
    byte[] result = new byte[totalLength];
    int offset = 0;
    for (ByteBuffer buffer : getBufferList()) {
        System.arraycopy(buffer.array(), buffer.position(), result, offset, buffer.remaining());
        offset += buffer.remaining();
    }
    return result;
}

